class Employee
    private define grossSalary as integer;

    method constructor(aSalary as integer)
        this.grossSalary <- aSalary;
    endMethod

    public method NetSalary(discount as integer) as real
        return this.grossSalary - this.grossSalary * discount / 100;
    endMethod
endClass

algorithm ComputeSalary
    define salary as integer;
    define discount as integer;
    define employee as Employee;
    read salary;
    read discount;
    employee <- new Employee(salary);
    write employee.NetSalary(discount);
endAlgorithm
